#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, long long>>> adj(n + 1);
    vector<int> indeg(n + 1, 0);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back({(int)e[1], e[2]});
        indeg[e[1]]++;
    }
    vector<int> queue;
    for (int v = 1; v <= n; v++) {
        if (indeg[v] == 0) queue.push_back(v);
    }
    vector<long long> best(n + 1, 0);
    for (size_t i = 0; i < queue.size(); i++) {
        int u = queue[i];
        for (const auto& edge : adj[u]) {
            int v = edge.first;
            if (best[u] + edge.second > best[v]) best[v] = best[u] + edge.second;
            indeg[v]--;
            if (indeg[v] == 0) queue.push_back(v);
        }
    }
    long long answer = 0;
    for (long long value : best) answer = max(answer, value);
    cout << answer << "\n";

    return 0;
}

